<?php $title='Media';require __DIR__.'/_layout.php';if(!can_manage('media'))exit('Forbidden');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$f=$_FILES['file']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>5*1024*1024)exit('Invalid upload');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp'];if(!isset($allowed[$mime]))exit('Only images are allowed');$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];$dir=__DIR__.'/../assets/uploads';if(!is_dir($dir))mkdir($dir,0755,true);move_uploaded_file($f['tmp_name'],$dir.'/'.$name);db()->prepare("INSERT INTO media(filename,original_name,mime_type,size_bytes,url,user_id) VALUES(?,?,?,?,?,?)")->execute([$name,$f['name'],$mime,$f['size'],site_url('assets/uploads/'.$name),current_user()['id']]);flash('success','Uploaded.');redirect('media.php');}$rows=db()->query("SELECT * FROM media ORDER BY created_at DESC")->fetchAll();?><h1>Media Library</h1><form class="form" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="file" name="file" accept="image/*" required><button>Upload</button></form><div class="grid"><?php foreach($rows as $m):?><div class="card"><img src="<?=e($m['url'])?>" alt="<?=e($m['original_name'])?>"><div class="pad"><?=e($m['original_name'])?><br><small><?=e($m['url'])?></small></div></div><?php endforeach;?></div><?php require __DIR__.'/_footer.php';?>